const raw = String($json.stdout ?? '').trim();
let result;
try {
  result = JSON.parse(raw);
} catch {
  throw new Error(String($json.stderr ?? '').trim() || raw || 'The downloader returned invalid JSON');
}

if (!Array.isArray(result.files) || result.files.length === 0 || !result.jobDirectory) {
  throw new Error(String(result.error ?? result.message ?? 'Odoriko produced no audio file'));
}

const track = result.tracks?.[0] ?? {};
return {
  chatId: '5759927190',
  jobDirectory: String(result.jobDirectory),
  remotePath: String(result.files[0]),
  fileName: String(track.fileName ?? result.files[0].split('/').pop() ?? 'Odoriko.mp3'),
  title: String(track.title ?? 'Odoriko'),
  artist: String(track.artist ?? 'Vaundy'),
  album: String(track.album ?? ''),
  duration: Number(track.duration) || 0,
  lyrics: String(track.lyrics ?? ''),
};
